function db(){return new Promise((resolve,reject)=>{const request=indexedDB.open('liss-operation-files-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Dateispeicher nicht verfügbar'));});}
async function fileTransaction(mode,action){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',mode),request=action(tx.objectStore('files'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>{database.close();resolve(result);};tx.onerror=tx.onabort=()=>{database.close();reject(Error('Datei nicht gespeichert / gelesen'));};});}
