async function restoreFullBackup(){const picker=input('file');picker.accept='.json';picker.onchange=async()=>{const file=picker.files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('Sicherung bis 100 MB');const data=JSON.parse(await file.text());if(data.format!=='liss-operations-backup-v1'||!Array.isArray(data.files))throw Error('Vollbackup auswählen');if(data.templateArchive&&(data.templateArchive.schema!==1||!Array.isArray(data.templateArchive.documents)))throw Error('Vorlagenarchiv ungültig');const loaded=P.valid(data.process),blobs=[];for(const meta of loaded.attachments||[]){const row=data.files.find(f=>f.id===meta.id);if(!row||!/^data:(application\/pdf|image\/jpeg|image\/png);base64,/.test(row.content)||row.size!==meta.size)throw Error('Anlage fehlt / Format ungültig');const bytes=Uint8Array.from(atob(row.content.split(',')[1]),c=>c.charCodeAt(0));if(bytes.length!==meta.size||bytes.length>10*1024*1024)throw Error('Anlagengröße ungültig');blobs.push([meta.id,new Blob([bytes],{type:meta.type})]);}if(!confirm('Daten durch diese Sicherung ersetzen? Der aktuelle vollständige Stand wird zuerst heruntergeladen.'))return;const revision=state().revision;await fullBackup();if(state().revision!==revision)throw Error('Daten geändert; Wiederherstellung abgebrochen');for(const [id,blob] of blobs){const existing=await fileTransaction('readonly',store=>store.get(id));if(existing){const a=await existing.arrayBuffer(),b=await blob.arrayBuffer();if(a.byteLength!==b.byteLength||new Uint8Array(a).some((v,i)=>v!==new Uint8Array(b)[i]))throw Error('Dateinummer kollidiert. Vorhandene Anlage nicht überschrieben.');}else await fileTransaction('readwrite',store=>store.put(blob,id));}if(state().revision!==revision)throw Error('Daten geändert; Wiederherstellung abgebrochen');const previousArchive=localStorage.getItem('liss-template-archive-demo-v1');try{if(data.templateArchive)localStorage.setItem('liss-template-archive-demo-v1',JSON.stringify(data.templateArchive));save(P.change({...loaded,revision},'Vollbackup wiederhergestellt','Disposition',()=>{}));}catch(e){if(previousArchive===null)localStorage.removeItem('liss-template-archive-demo-v1');else localStorage.setItem('liss-template-archive-demo-v1',previousArchive);throw e;}api.notice('Vollbackup wiederhergestellt.');}catch(e){api.notice('Nicht wiederhergestellt: '+e.message);}};picker.click();}
function archive(host){root.LissWorkCertificatesUI?.mount(host,api);dispatchOutbox(host);documentArchive(host);if(window.LissTeamSession){if(LissTeamSession.role==='owner')host.append(btn('Datensicherung · nur Inhaber',()=>location.href='LISS-Prozess.html'));else host.append(text('p','Vollständige Firmensicherung verwaltet der Inhaber.'));objectFilesArchive(host);return;}host.append(text('h3','Auftragsdateien & Sicherung'),row(btn('Vollbackup · Daten und Dateien',()=>fullBackup().catch(e=>api.notice('Sicherung abgebrochen: '+e.message))),btn('Vollbackup wiederherstellen',restoreFullBackup)),text('p','Das gewöhnliche Prozess-JSON enthält Datei-Verweise. Das Vollbackup enthält zusätzlich die hier hochgeladenen Dateien. Das Vollbackup enthält auch die bisherigen Vorlagen-Snapshots dieses Browserprofils.','muted'));for(const a of state().attachments||[]){const x=order(a.orderId);host.append(row(text('span',name(x?.objectId||a.objectId)+(x?' · V'+x.version:' · Besichtigung')+' · '+a.name),btn('Datei',()=>getFile(a.id).then(blob=>download(blob,a.name)).catch(e=>api.notice(e.message)))));}}
function objectFilesArchive(host){for(const a of state().attachments||[])host.append(row(text('span',a.name),btn('Datei herunterladen',()=>getFile(a.id).then(blob=>download(blob,a.name)).catch(e=>api.notice(e.message)))));}
function fileSharing(meta){const box=text('div',undefined,'ops-file-sharing');if(meta.purchaseInvoiceId)return text('p','Lieferantenbeleg · nur Inhaber');for(const [key,title] of [['employeeVisible','Mitarbeiter'],['customerVisible','Kunde']].filter(([key])=>!meta.invoiceId||key==='customerVisible')){const c=input('checkbox');c.checked=!!meta[key];c.onchange=()=>{try{save(P.change(state(),'Dateifreigabe geändert','Disposition',s=>{s.attachments.find(a=>a.id===meta.id)[key]=c.checked;}));}catch(e){c.checked=!c.checked;api.notice(e.message);}};box.append(api.label(title+' darf Datei öffnen',c));}return box;}
function objectFiles(host,oid){host.append(text('h3','Grundriss, Fotos & Dokumente'));const files=(state().attachments||[]).filter(a=>a.objectId===oid);if(!files.length)host.append(text('p','Noch keine Dateien angeheftet.','muted'));files.forEach(a=>host.append(row(text('span',a.name),btn('Herunterladen',()=>getFile(a.id).then(blob=>download(blob,a.name)).catch(e=>api.notice(e.message))))));if(window.LissTeamSession)files.forEach(a=>host.append(row(text('span',a.name),fileSharing(a))));host.append(btn('+ Datei anheften',()=>upload(null,oid)));}

function secretaryCase(type,id,focus){if(root.LissTeamSession&&!['owner','manager'].includes(root.LissTeamSession.role))throw Error('Nur Leitung');const time=new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()),cases=root.LissSecretary.cases(state(),{time,role:root.LissTeamSession?.role||'owner'}),current=cases.find(c=>c.type===type&&c.id===id&&c.focus===focus);if(!current){api.notice('Vorgang inzwischen geändert oder erledigt. Sekretariat aktualisiert.');api.show('secretary');return;}act(current);}
